<script setup>
import {ref,computed,onUnmounted} from 'vue'
import {marked} from 'marked'
import DOMPurify from 'dompurify'
import {useAuth} from '../stores/auth'
import {API_BASE,system,practice,practicePath,errorText,saveBlob,filename} from '../api/client'
import {copy,notify} from '../composables/ui'
import {validate,safeExample} from '../api/schema'
import {exclusive} from '../composables/cooldown'
import SchemaTable from './SchemaTable.vue'
import {pendingRequests} from '../stores/requests'
import {projectSuffix} from '../api/project-contract'
const props=defineProps({op:Object,cool:Object})
const auth=useAuth(),params=ref({}),form=ref({}),body=ref('{}'),error=ref(''),response=ref(null),preview=ref(''),open=ref(false)
const requestKey=`${auth.user?.userId}:${props.op.operationId}`
const busy=computed({get:()=>pendingRequests.has(requestKey),set:v=>v?pendingRequests.add(requestKey):pendingRequests.delete(requestKey)})
const json=computed(()=>props.op.requestBody?.content?.['application/json'])
const multipart=computed(()=>props.op.requestBody?.content?.['multipart/form-data'])
const parameters=computed(()=>props.op.parameters?.filter(p=>p.name!=='accessCode')||[])
const student=computed(()=>!auth.teacher),isPractice=computed(()=>props.op.project!=='system')
const executable=computed(()=>student.value||!isPractice.value)
const special=computed(()=>['/login','/logout'].includes(props.op.path))
const description=computed(()=>DOMPurify.sanitize(marked.parse(props.op.description||'')))
const fullUrl=computed(()=>{let path=props.op.path.replace('{accessCode}',auth.user?.apiAccessCode||'{本人访问码}');for(const p of parameters.value.filter(p=>p.in==='path'))if(params.value[p.name])path=path.replace(`{${p.name}}`,encodeURIComponent(params.value[p.name]));const q=new URLSearchParams();for(const p of parameters.value.filter(p=>p.in==='query'))if(params.value[p.name]!==''&&params.value[p.name]!=null)q.set(p.name,params.value[p.name]);return API_BASE+path+(q.size?'?'+q:'')})
function fill(){params.value={};for(const p of parameters.value)if(p.in!=='path'&&!/Id$|No$/.test(p.name)&&p.example!=null)params.value[p.name]=String(p.example);body.value=JSON.stringify(safeExample(json.value?.example||{}),null,2);notify('已填入示例。请从当前空间查询并填写真实ID。')}
function build(){const pathParams={},queryParams={};for(const p of parameters.value){const raw=params.value[p.name];if(raw===''||raw==null){if(p.required)throw new Error(`请填写 ${p.name}。`);continue}const v=['integer','number'].includes(p.schema?.type)?Number(raw):raw;const errors=validate(v,p.schema,p.name);if(errors.length)throw new Error(errors.join('；'));(p.in==='path'?pathParams:queryParams)[p.name]=v}
 let path=props.op.path;if(isPractice.value)path=practicePath(props.op.project,projectSuffix(props.op.project,path));for(const [k,v] of Object.entries(pathParams))path=path.replace(`{${k}}`,encodeURIComponent(v));if(path.includes('{'))throw new Error('请填写完整的路径参数。');let data
 if(json.value){try{data=JSON.parse(body.value)}catch{throw new Error('请求内容不是有效的 JSON，请检查逗号、引号和括号。')}const errors=validate(data,json.value.schema);if(errors.length)throw new Error(errors.join('；'))}
 if(multipart.value){data=new FormData();for(const [k,s]of Object.entries(multipart.value.schema.properties||{})){const raw=form.value[k];if(raw==null||raw===''){if(multipart.value.schema.required?.includes(k))throw new Error(`请填写或选择 ${k}`);continue}if(s.format==='binary'){if(raw.size>5*1024*1024)throw new Error('上传文件不能超过5MB。');data.append(k,raw)}else{const v=s.type==='integer'?Number(raw):raw;const errors=validate(v,s,k);if(errors.length)throw new Error(errors.join('；'));data.append(k,String(v))}}}
 return {method:props.op.method,url:path,params:queryParams,data,responseType:/\/images\/\{imageId\}\/(preview|download)$/.test(props.op.path)?'blob':'json'}
}
async function send(){if(busy.value)return;error.value='';let config;try{config=build()}catch(e){error.value=e.message;return}
 if(props.op.method!=='GET'&&!window.confirm(isPractice.value?'本次请求会修改你的实训数据。请确认参数和影响范围。':props.op.method==='DELETE'?'删除后将移除目标及关联学生、空间或项目数据，无法恢复。请确认影响范围。':props.op.path.includes('/reset')?'重置后，本项目中的操作数据将恢复为初始数据，请确认已保存需要保留的内容。':'本次请求会修改系统管理数据，请确认目标编号及影响范围。'))return
 busy.value=true;response.value=null;if(preview.value){URL.revokeObjectURL(preview.value);preview.value=''}
 async function perform(){if(student.value){props.cool.refresh();if(props.cool.seconds.value)throw new Error('请等待接口尝试冷却结束。');props.cool.start(10000)}const started=performance.now();const url=fullUrl.value;let r
 try{r=await (isPractice.value?practice:system).request(config)}catch(e){if(e.response)r=e.response;else{response.value={url,time:Math.round(performance.now()-started),status:'未收到响应',text:errorText(e)};throw e}}
 let data=r.data;if(data instanceof Blob){if(data.type.includes('json')||r.status>=400){try{data=JSON.parse(await data.text())}catch{data=await data.text()}}else{preview.value=URL.createObjectURL(data);response.value={url,time:Math.round(performance.now()-started),status:r.status,text:`图片返回成功，文件大小 ${data.size} 字节`,blob:data,filename:filename(r.headers)};return}}
 response.value={url,time:Math.round(performance.now()-started),status:r.status,text:typeof data==='string'?data:JSON.stringify(data,null,2)};if(r.status>=400||data?.code&&data.code!==200)error.value=data?.message||'请求未成功，请查看实际响应。'
 }
 try{if(student.value)await exclusive(props.cool.key,perform);else await perform()}catch(e){error.value=errorText(e)}finally{busy.value=false}
}
onUnmounted(()=>{if(preview.value)URL.revokeObjectURL(preview.value)})
</script>
<template><article class="endpoint" :class="op.method.toLowerCase()"><button class="endpoint-summary" :aria-expanded="open" @click="open=!open"><span class="method">{{op.method}}</span><code>{{op.path.replace('/api/practice/{accessCode}','')}}</code><strong>{{op.summary}}</strong><span class="chevron">{{open?'−':'＋'}}</span></button><div v-if="open" class="endpoint-body"><div class="prose" v-html="description"></div><p v-if="!executable" class="hint">教师可阅读业务接口定义。业务数据查询和试用请由学生在本人工作空间进行。</p><div class="url-copy"><code>{{fullUrl}}</code><button class="secondary" @click="copy(fullUrl)">复制完整地址</button></div><h3>参数要求</h3><div v-if="parameters.length" class="table-wrap"><table><thead><tr><th>参数</th><th>位置</th><th>要求</th><th>类型与说明</th></tr></thead><tbody><tr v-for="p in parameters" :key="p.name"><td><code>{{p.name}}</code></td><td>{{p.in==='path'?'路径':'查询'}}</td><td>{{p.required?'必填':'选填'}}</td><td>{{({string:'字符串',integer:'整数'})[p.schema.type]||p.schema.type}} · {{p.description}}<span v-if="p.schema.enum">（{{p.schema.enum.join('、')}}）</span></td></tr></tbody></table></div><SchemaTable v-if="json||multipart" :schema="(json||multipart).schema"/><p v-if="!parameters.length&&!json&&!multipart" class="hint">此接口无需填写额外参数。</p><details v-if="json"><summary>输入样例（示例ID须替换）</summary><pre>{{JSON.stringify(json.example,null,2)}}</pre></details><template v-if="executable&&!special"><h3>填写请求</h3><p v-if="isPractice" class="hint">请先查看参数要求，再填写请求内容。模拟用户ID请从当前工作空间的用户列表中获取。<RouterLink to="/data">查看真实数据 →</RouterLink></p><div class="parameter-grid"><label v-for="p in parameters" :key="p.name">{{p.name}} <small>{{p.required?'必填':'选填'}}</small><select v-if="p.schema.enum" v-model="params[p.name]"><option value="">请选择</option><option v-for="v in p.schema.enum" :key="v" :value="String(v)">{{v}}</option></select><input v-else v-model="params[p.name]" :aria-label="p.name" :placeholder="p.in==='path'||/Id$/.test(p.name)?'请填写当前数据中的真实编号':'请输入参数'"></label></div><label v-if="json">请求内容（JSON）<textarea v-model="body" rows="12" spellcheck="false" aria-label="JSON请求内容"></textarea></label><div v-if="multipart" class="parameter-grid"><label v-for="(s,k) in multipart.schema.properties" :key="k">{{k}} · {{s.description}}<input v-if="s.format==='binary'" type="file" :aria-label="k" @change="form[k]=$event.target.files[0]"><input v-else v-model="form[k]" :aria-label="k"></label></div><p v-if="op.method!=='GET'" class="alert warning">{{isPractice?'本次请求会修改你的实训数据。':'本次请求会修改系统管理数据。'}}</p><div class="toolbar"><button :disabled="busy||(student&&cool.seconds.value>0)" @click="send">{{busy?'请求进行中…':student&&cool.seconds.value?`${cool.seconds.value}秒后可再次发送`:'发送请求'}}</button><button class="secondary" :disabled="busy" @click="fill">填入示例参数</button></div></template><p v-if="special" class="hint">请通过平台的登录页或顶部“退出登录”完成此操作。</p><div v-if="error" role="alert" class="alert error">{{error}}</div><section v-if="response" class="response"><div class="section-heading"><h3>实际响应</h3><button class="secondary" @click="copy(response.text)">复制响应</button></div><div class="response-meta"><span>HTTP {{response.status}}</span><span>{{response.time}} 毫秒</span></div><code class="address">{{response.url}}</code><pre>{{response.text}}</pre><img v-if="preview" :src="preview" alt="接口返回图片" class="response-image"><button v-if="response.blob" class="secondary" @click="saveBlob(response.blob,response.filename)">下载图片</button></section><details><summary>返回码与输出样例</summary><div v-for="(r,code) in op.responses" :key="code" class="response-example"><b>{{code}}</b> {{r.description}}<pre v-if="r.content?.['application/json']?.example">{{JSON.stringify(r.content['application/json'].example,null,2)}}</pre><SchemaTable v-if="code==='200'" :schema="r.content?.['application/json']?.schema?.properties?.data?.items||r.content?.['application/json']?.schema?.properties?.data"/></div></details></div></article></template>
